<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">mysqlbinlog</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> --read-from-remote-server</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> --host=127.0.0.1</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> --user=backup</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> --password</span><span style="--shiki-light:#0184BC;--shiki-dark:#56B6C2;"> \\</span></span>
